
select "CL_BATCH_HEADER2"."NOTES", "CL_BATCH_HEADER2"."RCV_DATE", trim(both
 from "PV_PROVIDER3"."PROV_CODE"), "CL_BATCH_HEADER2"."CLM_SUBMISSION_TYPE", "CL_BATCH_HEADER2"."BATCH_ID", "CL_BATCH_HEADER2"."BATCH_STATUS_DESC", case  when SUBSTR("CL_BATCH_HEADER2"."PERIOD",5 ,2) is null  or SUBSTR("CL_BATCH_HEADER2"."PERIOD",1 ,4) is null  then  null  else '01/' || SUBSTR("CL_BATCH_HEADER2"."PERIOD",5 ,2) || '/' || SUBSTR("CL_BATCH_HEADER2"."PERIOD",1 ,4) end , "CL_BATCH_HEADER2"."TPA", case  when "CL_BATCH_HEADER2"."CLM_SUBMISSION_TYPE" in ('Nphies', 'DHS', 'Direct Integration') then 'INTEGRATION' else 'NON-INTEGRATION' end , "CL_BATCH_HEADER2"."CRT_DATE", (nvl("CL_BATCH_HEADER2"."BILL_PRESENT_AMT", 0) - nvl("CL_BATCH_HEADER2"."BILL_DISC_AMT", 0)) - nvl("CL_BATCH_HEADER2"."BILL_DEDUCT_AMT", 0), "CL_BATCH_HEADER2"."VAT_AMT"
 from (
select "CL_BATCH_HEADER"."BATCH_ID", "CL_BATCH_HEADER"."PROV_CODE", "CL_BATCH_HEADER"."RCV_DATE", "CL_BATCH_HEADER"."PERIOD", "CL_BATCH_HEADER"."BILL_PRESENT_AMT", "CL_BATCH_HEADER"."BILL_DISC_AMT", "CL_BATCH_HEADER"."BILL_DEDUCT_AMT", "CL_BATCH_HEADER"."CRT_DATE", "CL_BATCH_HEADER"."NOTES", "CL_BATCH_HEADER"."VAT_AMT", "SY_STATUS_BATCH_HEADER"."EDESC" "BATCH_STATUS_DESC", "SYS_SUBMIS_TYPE"."EDESC" "CLM_SUBMISSION_TYPE", "CL_BATCH_HEADER"."TPA"
 from ("CSR"."CL_BATCH_HEADER" "CL_BATCH_HEADER" INNER JOIN "CSR"."SY_STATUS_BATCH_HEADER" "SY_STATUS_BATCH_HEADER" on "CL_BATCH_HEADER"."STATUS"="SY_STATUS_BATCH_HEADER"."SYS_CODE") LEFT OUTER JOIN "CSR"."SY_SYS_CODE" "SYS_SUBMIS_TYPE" on "CL_BATCH_HEADER"."CLM_SUBMIS_TYPE"="SYS_SUBMIS_TYPE"."SYS_CODE" and 'CLM_SUBMISSION_TYPE'="SYS_SUBMIS_TYPE"."SYS_TYPE") "CL_BATCH_HEADER2", (
select "PV_PROVIDER"."PROV_CODE"
 from (((((("CSR"."PV_PROVIDER" "PV_PROVIDER" INNER JOIN "CSR"."DC_DISTRICT" "DC_DISTRICT" on "PV_PROVIDER"."CORR_DIST_CODE"="DC_DISTRICT"."DIST_CODE") LEFT OUTER JOIN "CSR"."SY_PROVIDER_LEVEL" "SY_PROVIDER_LEVEL1" on "PV_PROVIDER"."PROV_LEVEL"="SY_PROVIDER_LEVEL1"."SYS_CODE") LEFT OUTER JOIN "CSR"."SY_PRACTICE_TYPE" "SY_PRACTICE_TYPE" on "PV_PROVIDER"."PRACTICE_TYPE"="SY_PRACTICE_TYPE"."SYS_CODE") LEFT OUTER JOIN "CSR"."PV_PROV_LVL_MVMNT" on "PV_PROVIDER"."PROV_CODE"="PV_PROV_LVL_MVMNT"."PROV_CODE") LEFT OUTER JOIN "CSR"."SY_PROVIDER_LEVEL" "SY_PROVIDER_LEVEL2" on "PV_PROV_LVL_MVMNT"."PROV_LEVEL"="SY_PROVIDER_LEVEL2"."SYS_CODE") LEFT OUTER JOIN "CSR"."SY_SYS_CODE" "VRS" on "PV_PROVIDER"."VAT_REG_STATUS"=trim(both
 from "VRS"."SYS_CODE") and 'VAT_REG_STATUS'=trim(both
 from "VRS"."SYS_TYPE")) LEFT OUTER JOIN "CSR"."SY_SYS_CODE" "CTC" on "PV_PROVIDER"."CTRY_CODE"=trim(both
 from "CTC"."SYS_CODE") and 'COUNTRY_CODE'=trim(both
 from "CTC"."SYS_TYPE")
 where "PV_PROV_LVL_MVMNT"."END_DATE" is null and "PV_PROVIDER"."PRACTICE_TYPE"<>280) "PV_PROVIDER3"
 where "CL_BATCH_HEADER2"."PROV_CODE"="PV_PROVIDER3"."PROV_CODE" and "CL_BATCH_HEADER2"."BATCH_STATUS_DESC"<>'Rework' and "CL_BATCH_HEADER2"."RCV_DATE"<=TRUNC( CURRENT_DATE ) and "CL_BATCH_HEADER2"."RCV_DATE">=DATE '2025-01-01'
